package com.bank.jvm;

import java.math.BigDecimal;
import java.util.logging.*;

// Shows interpreted (cold) vs JIT-compiled (warm) performance of a hot method.
public class JitDemo {
    private static final Logger log = Logger.getLogger(JitDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        InterestCalculator calc = new InterestCalculator();
        TimingHarness harness = new TimingHarness();

        // COLD window: method is still interpreted / only C1-compiled.
        long coldOps = harness.measure(calc, 500_000, "COLD (startup, pre-JIT)");

        // Keep hammering the method so it becomes hot and C2 compiles it.
        harness.warmUp(calc, 5_000_000);

        // WARM window: method now runs as C2-optimized native code.
        long warmOps = harness.measure(calc, 500_000, "WARM (after JIT C2)");

        log.info(String.format("Throughput improved ~%.1fx after JIT warm-up",
                (double) warmOps / Math.max(1, coldOps)));
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in InterestCalculator.java in a real project ───
class InterestCalculator {
    private static final BigDecimal DAYS = new BigDecimal("365");
    // The hot method: compiled to native code once it is called enough times.
    BigDecimal calculateInterest(BigDecimal principal, BigDecimal annualRate) {
        return principal.multiply(annualRate)
                .divide(DAYS, 6, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Would be in TimingHarness.java in a real project ───
class TimingHarness {
    private static final Logger log = Logger.getLogger(TimingHarness.class.getName());
    private static final BigDecimal PRINCIPAL = new BigDecimal("1000000");
    private static final BigDecimal RATE = new BigDecimal("0.065");

    // Call the hot method many times just to trigger JIT compilation.
    void warmUp(InterestCalculator calc, int iterations) {
        BigDecimal sink = BigDecimal.ZERO;
        for (int i = 0; i < iterations; i++) {
            sink = sink.add(calc.calculateInterest(PRINCIPAL, RATE));
        }
        log.fine(() -> "warm-up sink=" + sink); // consume result so it is not optimized away
    }

    // Measure how many operations complete in a fixed window; consume the result.
    long measure(InterestCalculator calc, int iterations, String label) {
        BigDecimal sink = BigDecimal.ZERO;
        long start = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            sink = sink.add(calc.calculateInterest(PRINCIPAL, RATE));
        }
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;
        long opsPerMs = elapsedMs == 0 ? iterations : iterations / elapsedMs;
        log.info(String.format("%-24s iterations=%d elapsed=%dms opsPerMs=%d (sink=%s)",
                label, iterations, elapsedMs, opsPerMs, sink.signum()));
        return opsPerMs;
    }
}
